script:
var doc = Document;
// Goal: enclose a 20' x 15' room footprint with walls of a named type on a level, joined at the corners.
// Reads (finding the level and the type) happen at top level; every write sits inside one WithTransaction block.
// A blank project has levels already; take the lowest one rather than creating another.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (level == null || l.Elevation < level.Elevation) level = l;
}

// 1. Choose the wall type by name. Names are case-sensitive and template-dependent, so fall back to
//    the first Basic wall type (WallKind.Basic) rather than failing on a name the template lacks.
//    Curtain and stacked types also derive from WallType, which is why Kind is checked.
string wantedTypeName = "Generic - 8\"";
Autodesk.Revit.DB.WallType wallType = null;
Autodesk.Revit.DB.WallType firstBasic = null;
foreach (Autodesk.Revit.DB.WallType wt in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.WallType))) {
  if (wt.Kind != Autodesk.Revit.DB.WallKind.Basic) continue;
  if (firstBasic == null) firstBasic = wt;
  if (wt.Name == wantedTypeName) { wallType = wt; break; }
}
bool usedFallback = wallType == null;
if (wallType == null) wallType = firstBasic;
if (wallType == null) throw new System.Exception("no Basic wall type in this document");

// 2. The footprint as corner points, in feet (Revit's internal length unit), on the level's elevation.
double z = level.Elevation;
var corners = new[] {
  new Autodesk.Revit.DB.XYZ(0, 0, z), new Autodesk.Revit.DB.XYZ(20, 0, z),
  new Autodesk.Revit.DB.XYZ(20, 15, z), new Autodesk.Revit.DB.XYZ(0, 15, z) };

return Connector.WithTransaction(doc, () => {
  // 3. One wall per edge, drawn head-to-tail so each wall's end meets the next wall's start.
  //    This Wall.Create overload takes the type, the level, a height (10'), a base offset (0),
  //    flip=false and structural=false; the shorter overload (doc, line, levelId, structural)
  //    uses the document's default wall type instead of a chosen one.
  var walls = new Autodesk.Revit.DB.Wall[4];
  for (int i = 0; i < 4; i++) {
    var line = Autodesk.Revit.DB.Line.CreateBound(corners[i], corners[(i + 1) % 4]);
    walls[i] = Autodesk.Revit.DB.Wall.Create(doc, line, wallType.Id, level.Id, 10.0, 0.0, false, false);
  }
  // 4. Regenerate before reading geometry or joins back: until then the location curves and
  //    the end joins are not resolved.
  doc.Regenerate();

  // 5. Verify the loop closes: each wall's end point equals the next wall's start point.
  bool loopCloses = true;
  for (int i = 0; i < 4; i++) {
    var a = ((Autodesk.Revit.DB.LocationCurve)walls[i].Location).Curve.GetEndPoint(1);
    var b = ((Autodesk.Revit.DB.LocationCurve)walls[(i + 1) % 4].Location).Curve.GetEndPoint(0);
    if (!a.IsAlmostEqualTo(b)) loopCloses = false;
  }

  // 6. Verify the corners join. For walls, "do the corners join" means WALL-END joins, read per
  //    end (0 = start, 1 = end) from the wall's LocationCurve: get_ElementsAtJoin(end) lists the
  //    elements joined at that end, so a joined corner has at least one. Two APIs look right and
  //    are not: WallUtils.IsWallJoinAllowedAtEnd only reports the Allow/Disallow Join toggle (true
  //    for a lone wall with nothing at its end), so it is the precondition, not the check; and
  //    JoinGeometryUtils.AreElementsJoined reports geometry joins (the Join Geometry command),
  //    which fresh walls do not have.
  int cornersJoined = 0;
  bool allEndsAllowJoin = true;
  foreach (var w in walls) {
    var lc = (Autodesk.Revit.DB.LocationCurve)w.Location;
    for (int end = 0; end < 2; end++) {
      if (!Autodesk.Revit.DB.WallUtils.IsWallJoinAllowedAtEnd(w, end)) allEndsAllowJoin = false;
      if (lc.get_ElementsAtJoin(end).Size > 0) cornersJoined++;
    }
  }

  // 7. Return a projection, never the elements themselves.
  var ids = new long[4];
  for (int i = 0; i < 4; i++) ids[i] = walls[i].Id.Value;
  // cornersJoined counts wall ENDS with a join partner: 8 for a closed loop of four walls.
  return new { wallIds = ids, wallType = wallType.Name, usedFallbackType = usedFallback, level = level.Name, loopCloses, allEndsAllowJoin, cornersJoined, allCornersJoined = cornersJoined == 8 };
});
